import React, { useRef } from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { Modal } from '../../..';

describe('Modal', () => {
  it('should render', () => {
    render(
      <Modal.Root
        trigger={<button type="button">Open</button>}
        title={<h2>Modal Title</h2>}
        actions={
          <>
            <Modal.Cancel>
              <button type="button">Cancel</button>
            </Modal.Cancel>
            <Modal.Action>
              <button type="button">Cancel</button>
            </Modal.Action>
          </>
        }
      >
        <p>Modal Body</p>
      </Modal.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Modal Title')).toBeInTheDocument();
    expect(screen.getByText('Modal Body')).toBeInTheDocument();
  });
  it('should render with headerImage', () => {
    render(
      <Modal.Root
        trigger={<button type="button">Open</button>}
        headerHeight="15rem"
        headerImage={
          <div
            data-testid="image-div"
            style={{
              height: '70%',
              backgroundColor: 'rgba(255, 0, 0, 0.3)',
              borderTopLeftRadius: '1.5rem',
              borderTopRightRadius: '1.5rem',
            }}
          />
        }
        actions={
          <>
            <Modal.Cancel>
              <button type="button">Cancel</button>
            </Modal.Cancel>
            <Modal.Action>
              <button type="button">Cancel</button>
            </Modal.Action>
          </>
        }
      >
        <p>Modal Body</p>
      </Modal.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByTestId('image-div')).toBeInTheDocument();
  });
  it('should pass refs', () => {
    const UseRef = () => {
      const ref = useRef(null);
      return (
        <Modal.Root
          ref={ref}
          trigger={<button type="button">Open</button>}
          title={<h2>Modal Title</h2>}
          actions={
            <>
              <Modal.Cancel>
                <button type="button">Cancel</button>
              </Modal.Cancel>
              <Modal.Action>
                <button type="button">Cancel</button>
              </Modal.Action>
            </>
          }
        >
          <p>Modal Body</p>
        </Modal.Root>
      );
    };
    render(<UseRef />);
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByText('Modal Body')).toBeInTheDocument();
  });

  it('should render with variant destructive', () => {
    render(
      <Modal.Root destructive="critical" trigger={<button type="button">Open</button>}>
        <p>Dialog Body</p>
      </Modal.Root>
    );
    fireEvent.click(screen.getByText('Open'));
    expect(screen.getByTestId('destructive')).toBeInTheDocument();
  });
});
